def hanoi(n, source, target, auxiliary):
    """Solve Tower of Hanoi for n disks."""
    if n <= 0:
        return []
    moves = []
    moves.extend(hanoi(n - 1, source, auxiliary, target))
    moves.append((source, target))
    moves.extend(hanoi(n - 1, auxiliary, target, source))
    return moves

def hanoi_iterative(n):
    total = 2 ** n - 1
    pegs = {'A': [], 'B': [], 'C': []}
    for i in range(n, 0, -1):
        pegs['A'].append(i)
    moves = []
    if n % 2 == 0:
        order = ['A', 'B', 'C']
    else:
        order = ['A', 'C', 'B']
    for i in range(1, total + 1):
        if i % 3 == 1:
            _move(pegs, order[0], order[1], moves)
        elif i % 3 == 2:
            _move(pegs, order[0], order[2], moves)
        else:
            _move(pegs, order[1], order[2], moves)
    return moves

def _move(pegs, a, b, moves):
    if not pegs[a] and not pegs[b]:
        return
    if not pegs[a]:
        pegs[a].append(pegs[b].pop())
        moves.append((b, a))
    elif not pegs[b]:
        pegs[b].append(pegs[a].pop())
        moves.append((a, b))
    elif pegs[a][-1] < pegs[b][-1]:
        pegs[b].append(pegs[a].pop())
        moves.append((a, b))
    else:
        pegs[a].append(pegs[b].pop())
        moves.append((b, a))

def solve_n_queens(n):
    """Return all solutions for the N-Queens problem."""
    solutions = []
    board = [-1] * n

    def is_safe(row, col):
        for prev_row in range(row):
            prev_col = board[prev_row]
            if prev_col == col:
                return False
            if abs(prev_row - row) == abs(prev_col - col):
                return False
        return True

    def solve(row):
        if row == n:
            solutions.append(list(board))
            return
        for col in range(n):
            if is_safe(row, col):
                board[row] = col
                solve(row + 1)
                board[row] = -1

    solve(0)
    return solutions

def format_board(solution):
    n = len(solution)
    lines = []
    for row in range(n):
        line = ['.'] * n
        line[solution[row]] = 'Q'
        lines.append(' '.join(line))
    return '\n'.join(lines)

def knapsack_01(weights, values, capacity):
    """0/1 Knapsack using dynamic programming."""
    n = len(weights)
    dp = [[0] * (capacity + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for w in range(capacity + 1):
            dp[i][w] = dp[i - 1][w]
            if weights[i - 1] <= w:
                dp[i][w] = max(dp[i][w],
                               dp[i - 1][w - weights[i - 1]] + values[i - 1])
    # Backtrack to find selected items
    selected = []
    w = capacity
    for i in range(n, 0, -1):
        if dp[i][w] != dp[i - 1][w]:
            selected.append(i - 1)
            w -= weights[i - 1]
    selected.reverse()
    return dp[n][capacity], selected

def fractional_knapsack(weights, values, capacity):
    items = sorted(range(len(weights)),
                   key=lambda i: values[i] / weights[i], reverse=True)
    total = 0.0
    for i in items:
        if capacity <= 0:
            break
        take = min(weights[i], capacity)
        total += take * (values[i] / weights[i])
        capacity -= take
    return total

def compute_failure(pattern):
    """Compute KMP failure function."""
    m = len(pattern)
    failure = [0] * m
    j = 0
    for i in range(1, m):
        while j > 0 and pattern[i] != pattern[j]:
            j = failure[j - 1]
        if pattern[i] == pattern[j]:
            j += 1
        failure[i] = j
    return failure

def kmp_search(text, pattern):
    """Find all occurrences of pattern in text using KMP."""
    n, m = len(text), len(pattern)
    if m == 0:
        return []
    failure = compute_failure(pattern)
    matches = []
    j = 0
    for i in range(n):
        while j > 0 and text[i] != pattern[j]:
            j = failure[j - 1]
        if text[i] == pattern[j]:
            j += 1
        if j == m:
            matches.append(i - m + 1)
            j = failure[j - 1]
    return matches

def naive_search(text, pattern):
    matches = []
    for i in range(len(text) - len(pattern) + 1):
        if text[i:i + len(pattern)] == pattern:
            matches.append(i)
    return matches

class AVLNode:
    def __init__(self, key):
        self.key = key
        self.left = None
        self.right = None
        self.height = 1

class AVLTree:
    def __init__(self):
        self.root = None

    def height(self, node):
        return node.height if node else 0

    def balance_factor(self, node):
        return self.height(node.left) - self.height(node.right) if node else 0

    def update_height(self, node):
        node.height = 1 + max(self.height(node.left), self.height(node.right))

    def rotate_right(self, y):
        x = y.left
        t = x.right
        x.right = y
        y.left = t
        self.update_height(y)
        self.update_height(x)
        return x

    def rotate_left(self, x):
        y = x.right
        t = y.left
        y.left = x
        x.right = t
        self.update_height(x)
        self.update_height(y)
        return y

    def insert(self, key):
        self.root = self._insert(self.root, key)

    def _insert(self, node, key):
        if not node:
            return AVLNode(key)
        if key < node.key:
            node.left = self._insert(node.left, key)
        elif key > node.key:
            node.right = self._insert(node.right, key)
        else:
            return node
        self.update_height(node)
        bf = self.balance_factor(node)
        if bf > 1 and key < node.left.key:
            return self.rotate_right(node)
        if bf < -1 and key > node.right.key:
            return self.rotate_left(node)
        if bf > 1 and key > node.left.key:
            node.left = self.rotate_left(node.left)
            return self.rotate_right(node)
        if bf < -1 and key < node.right.key:
            node.right = self.rotate_right(node.right)
            return self.rotate_left(node)
        return node

    def inorder(self):
        result = []
        self._inorder(self.root, result)
        return result

    def _inorder(self, node, result):
        if node:
            self._inorder(node.left, result)
            result.append(node.key)
            self._inorder(node.right, result)

import heapq

def dijkstra(graph, start):
    """Dijkstra shortest path from start to all nodes."""
    dist = {start: 0}
    prev = {start: None}
    pq = [(0, start)]
    visited = set()
    while pq:
        d, u = heapq.heappop(pq)
        if u in visited:
            continue
        visited.add(u)
        for v, w in graph.get(u, []):
            alt = d + w
            if v not in dist or alt < dist[v]:
                dist[v] = alt
                prev[v] = u
                heapq.heappush(pq, (alt, v))
    return dist, prev

def reconstruct_path(prev, target):
    path = []
    node = target
    while node is not None:
        path.append(node)
        node = prev.get(node)
    path.reverse()
    return path

def bellman_ford(edges, n, start):
    dist = [float('inf')] * n
    dist[start] = 0
    for _ in range(n - 1):
        for u, v, w in edges:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
    for u, v, w in edges:
        if dist[u] + w < dist[v]:
            raise ValueError("Negative cycle")
    return dist

def coin_change(coins, amount):
    """Minimum coins to make amount (DP)."""
    dp = [float('inf')] * (amount + 1)
    dp[0] = 0
    parent = [-1] * (amount + 1)
    for i in range(1, amount + 1):
        for c in coins:
            if c <= i and dp[i - c] + 1 < dp[i]:
                dp[i] = dp[i - c] + 1
                parent[i] = c
    if dp[amount] == float('inf'):
        return -1, []
    # Reconstruct solution
    result = []
    a = amount
    while a > 0:
        result.append(parent[a])
        a -= parent[a]
    return dp[amount], result

def coin_change_ways(coins, amount):
    """Count number of ways to make amount."""
    dp = [0] * (amount + 1)
    dp[0] = 1
    for c in coins:
        for i in range(c, amount + 1):
            dp[i] += dp[i - c]
    return dp[amount]

def coin_change_greedy(coins, amount):
    coins_sorted = sorted(coins, reverse=True)
    result = []
    for c in coins_sorted:
        while amount >= c:
            result.append(c)
            amount -= c
    return result if amount == 0 else None

def matrix_chain_order(dims):
    """Matrix chain multiplication — minimum scalar multiplications."""
    n = len(dims) - 1
    dp = [[0] * n for _ in range(n)]
    split = [[0] * n for _ in range(n)]
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            dp[i][j] = float('inf')
            for k in range(i, j):
                cost = dp[i][k] + dp[k + 1][j] + dims[i] * dims[k + 1] * dims[j + 1]
                if cost < dp[i][j]:
                    dp[i][j] = cost
                    split[i][j] = k
    return dp[0][n - 1], split

def print_optimal_parens(split, i, j):
    if i == j:
        return f"A{i}"
    k = split[i][j]
    left = print_optimal_parens(split, i, k)
    right = print_optimal_parens(split, k + 1, j)
    return f"({left} x {right})"

def matrix_multiply(A, B):
    rows_a, cols_a = len(A), len(A[0])
    rows_b, cols_b = len(B), len(B[0])
    if cols_a != rows_b:
        raise ValueError("Incompatible dimensions")
    result = [[0] * cols_b for _ in range(rows_a)]
    for i in range(rows_a):
        for j in range(cols_b):
            for k in range(cols_a):
                result[i][j] += A[i][k] * B[k][j]
    return result

def interval_scheduling(intervals):
    """Greedy interval scheduling maximization."""
    sorted_intervals = sorted(intervals, key=lambda x: x[1])
    selected = []
    last_end = float('-inf')
    for start, end in sorted_intervals:
        if start >= last_end:
            selected.append((start, end))
            last_end = end
    return selected

def weighted_interval_scheduling(intervals):
    """Weighted interval scheduling via DP."""
    intervals = sorted(intervals, key=lambda x: x[1])
    n = len(intervals)
    dp = [0] * (n + 1)
    def latest_compatible(i):
        lo, hi = 0, i - 1
        while lo <= hi:
            mid = (lo + hi) // 2
            if intervals[mid][1] <= intervals[i][0]:
                if mid + 1 < i and intervals[mid + 1][1] <= intervals[i][0]:
                    lo = mid + 1
                else:
                    return mid + 1
            else:
                hi = mid - 1
        return 0
    for i in range(1, n + 1):
        incl = intervals[i - 1][2] + dp[latest_compatible(i - 1)]
        dp[i] = max(dp[i - 1], incl)
    return dp[n]

def count_overlaps(intervals):
    events = []
    for s, e in intervals:
        events.append((s, 1))
        events.append((e, -1))
    events.sort()
    max_overlap = current = 0
    for _, delta in events:
        current += delta
        max_overlap = max(max_overlap, current)
    return max_overlap

from collections import defaultdict, deque

def topological_sort_kahn(graph, n):
    """Kahn's algorithm for topological sort."""
    in_degree = [0] * n
    for u in range(n):
        for v in graph.get(u, []):
            in_degree[v] += 1
    queue = deque([u for u in range(n) if in_degree[u] == 0])
    order = []
    while queue:
        u = queue.popleft()
        order.append(u)
        for v in graph.get(u, []):
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)
    if len(order) != n:
        raise ValueError("Graph has a cycle")
    return order

def topological_sort_dfs(graph, n):
    """DFS-based topological sort."""
    visited = [False] * n
    stack = []
    def dfs(u):
        visited[u] = True
        for v in graph.get(u, []):
            if not visited[v]:
                dfs(v)
        stack.append(u)
    for u in range(n):
        if not visited[u]:
            dfs(u)
    stack.reverse()
    return stack

def all_topological_sorts(graph, n):
    in_degree = [0] * n
    for u in range(n):
        for v in graph.get(u, []):
            in_degree[v] += 1
    results = []
    visited = [False] * n
    current = []
    def backtrack():
        if len(current) == n:
            results.append(list(current))
            return
        for u in range(n):
            if not visited[u] and in_degree[u] == 0:
                visited[u] = True
                current.append(u)
                for v in graph.get(u, []):
                    in_degree[v] -= 1
                backtrack()
                current.pop()
                visited[u] = False
                for v in graph.get(u, []):
                    in_degree[v] += 1
    backtrack()
    return results
